package com.voicetxt.reader;

import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;

/** Two invocations deliberately separated by process death; original settings are restored in verify. */
public class VoiceSelectionRestoreTest extends VoiceWarmupTest {
    boolean prepare;
    public void onCreate(Bundle args){prepare=args!=null&&"prepare".equals(args.getString("phase"));super.onCreate(args);}
    MainActivity openReader(){return (MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","voice_selection_restore_qa").putExtra("book_name","音色恢复验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
    public void onStart(){Bundle result=new Bundle();SharedPreferences prefs=getTargetContext().getSharedPreferences("reading_settings",0);File backup=new File(getTargetContext().getFilesDir(),"voice-selection-qa.backup"),expectedFile=new File(getTargetContext().getFilesDir(),"voice-selection-qa.key");MainActivity reader=null;OfflineVoicesActivity manager=null;boolean success=false;Map<String,?> original=null;
        try{
            if(prepare){check(!backup.exists(),"Unrestored QA settings backup exists");original=new HashMap<>(prefs.getAll());try(ObjectOutputStream out=new ObjectOutputStream(new FileOutputStream(backup))){out.writeObject(original);}
                reader=openReader();final MainActivity initial=reader;await(()->initial.system!=null&&initial.system.initialized,"System discovery not ready",30000);String choice=null;for(SystemSpeaker.Option voice:initial.system.options)if(SystemSpeaker.offlineUsable(voice.voice)&&VoiceLanguages.matches("zh",voice.voice.getLocale())&&(voice.engine.toLowerCase(Locale.ROOT).contains("honor")||voice.engineLabel.contains("荣耀")))choice=voice.key;check(choice!=null,"Honor Chinese voice missing");check(!VoicePackages.get(initial).list("zh").isEmpty(),"Need imported Chinese model to expose fallback bug");final String desired=choice;
                prefs.edit().putString("readingLanguage","zh").commit();ui(initial::finish);reader=null;
                manager=(OfflineVoicesActivity)startActivitySync(new Intent(getTargetContext(),OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final OfflineVoicesActivity m=manager;await(()->m.system!=null&&m.system.initialized,"Manager discovery not ready",30000);ui(()->{OfflineVoicesActivity.Item item=null;for(OfflineVoicesActivity.Item candidate:m.items("zh"))if(candidate.key.equals("system:"+desired))item=candidate;check(item!=null,"Manager voice item missing");m.select(item);check(m.selectedKey("zh").equals("system:"+desired),"Manager failed to select exact Honor voice");});prefs.edit().commit();Files.write(expectedFile.toPath(),desired.getBytes(StandardCharsets.UTF_8));result.putString("expectedVoice",desired);result.putString("result","PREPARED: selected exact Honor Chinese voice through manager; close/force-stop app before verify");success=true;
            }else{
                check(backup.isFile()&&expectedFile.isFile(),"Run prepare first");try(ObjectInputStream input=new ObjectInputStream(new FileInputStream(backup))){original=(Map<String,?>)input.readObject();}String expected=new String(Files.readAllBytes(expectedFile.toPath()),StandardCharsets.UTF_8);
                reader=openReader();final MainActivity a=reader;ui(()->{check(a.readingLanguage.equals("zh"),"Reading language not restored");check(a.systemVoiceKey.equals(expected),"Startup replaced saved Honor voice with: "+a.systemVoiceKey);check(a.offline==null,"Startup preloaded an unwanted imported model");});await(()->a.system.initialized,"Reader discovery not ready",30000);
                ui(()->{check(a.ensureReadingVoice()&&a.systemVoiceKey.equals(expected),"Ready engine did not restore exact Honor voice");ArrayList<SystemSpeaker.Option> options=new ArrayList<>(a.system.options);a.system.options.clear();a.system.initialized=false;try{check(!a.ensureReadingVoice(),"Uninitialized engine treated as available");check(a.systemVoiceKey.equals(expected),"Delayed discovery replaced saved voice");a.warmCurrentModel();check(a.offline==null,"Delayed discovery loaded imported model");}finally{a.system.options.addAll(options);a.system.initialized=true;}a.chooseVoice();check(a.voicePicker.host.selectedKey().equals("system:"+expected),"Reader picker selected wrong voice");a.voicePicker.dismiss();a.finish();});reader=null;
                manager=(OfflineVoicesActivity)startActivitySync(new Intent(getTargetContext(),OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final OfflineVoicesActivity m=manager;ui(()->check(!m.selectedKey("zh").startsWith("pack:"),"Manager falsely selected imported voice while loading"));await(()->m.system.initialized,"Manager discovery not ready",30000);ui(()->{check(m.selectedKey("zh").equals("system:"+expected),"Manager failed to restore exact Honor voice");m.finish();});manager=null;
                VoiceModel pack=VoicePackages.get(getTargetContext()).list("zh").get(0);int speaker=Math.min(73,pack.speakers-1);check(speaker>0,"Need multi-speaker model for ordinal restore test");String imported=pack.key(speaker);prefs.edit().putString(MainActivity.readingVoicePreference("zh"),imported).putString("systemVoiceKey",pack.key(0)).commit();reader=openReader();final MainActivity b=reader;ui(()->check(b.systemVoiceKey.equals(imported),"Stale global key replaced per-language speaker"));await(()->b.offline instanceof PackageSpeaker&&((PackageSpeaker)b.offline).ready,"Selected imported model not preloaded",30000);ui(()->check(((PackageSpeaker)b.offline).selection.speaker==speaker,"Imported voice reset to first speaker"));
                result.putString("result","PASS: exact Honor voice and Chinese reading language survive process restart; pending engine discovery does not select/preload imported model; both voice pickers restore Honor; non-first imported speaker follows language preference despite stale global key");success=true;
            }
            result.putInt("pid",android.os.Process.myPid());
        }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}
        finally{if(reader!=null){final MainActivity a=reader;ui(()->{a.stop();a.finish();});}if(manager!=null){final OfflineVoicesActivity a=manager;ui(a::finish);}waitForIdleSync();if((!prepare||!success)&&original!=null){restore(prefs,original);backup.delete();expectedFile.delete();}getTargetContext().getSharedPreferences("reader_voice_selection_restore_qa",0).edit().clear().commit();new File(getTargetContext().getFilesDir(),"book_voice_selection_restore_qa.txt.position").delete();}
        finish(success?-1:0,result);
    }
}
